using System;
using System.Collections.Generic;
using System.Globalization;
using System.Text;
using Blockparty.AI;
using Blockparty.Contracts;
using Blockparty.UI;
using UnityEngine;

// CONTROLS-LOGO (M5-OD-36, M5-OD-37): the Settings > Controls rebind page and
// the title logo, drawn with the AlphaHud panels and palette. The page is
// modal: while it is open AlphaHud.Draw shows only this card and
// AlphaDirector routes keys through AlphaControlsInput. The logo is
// UI/Art/Resources/BlockPartyLogo.png, generated by
// evidence/production/CONTROLS-LOGO/tools/make-logo.py.
public sealed partial class AlphaHud
{
    public sealed partial class Frame
    {
        public ControlsRebind Controls;
    }

    const float TitleLogoH = 176f;
    const int ControlsCols = 3;
    Texture2D logo;
    string controlsLayoutKey;

    void DrawLogo(Rect r)
    {
        if (logo == null) logo = Resources.Load<Texture2D>("BlockPartyLogo");
        if (logo == null) { FitText(r, "Block Party", 46, Ink, true, TextAnchor.MiddleCenter); return; }
        if (Event.current.type == EventType.Repaint) GUI.DrawTexture(r, logo, ScaleMode.ScaleToFit, true);
    }

    // Every action plus the hold-to-talk row (VOICE-LIVE).
    static int ControlsPerCol { get { return (ControlsRebind.ActionCount + 1 + ControlsCols - 1) / ControlsCols; } }
    const string TalkLabel = "Talk (hold)";

    float ControlsChipW() { return Mathf.Max(U(96), Measure("Press a key", 14) + U(24)); }

    // Columns fit the longest label plus a key chip at the current text scale; the card is clamped to the screen.
    Rect ControlsCard(out float colW)
    {
        float label = 0f;
        foreach (string a in InputActions.Names) label = Mathf.Max(label, Measure(ControlsRebind.Label(a), 15));
        label = Mathf.Max(label, Measure(TalkLabel, 15));
        colW = label + U(34) + ControlsChipW();
        float w = Mathf.Min(U(48) + ControlsCols * colW + (ControlsCols - 1) * U(14), Screen.width - U(24));
        colW = (w - U(48) - (ControlsCols - 1) * U(14)) / ControlsCols;
        float h = ControlsRowsTop() + ControlsPerCol * U(48) + U(6) + U(40) + U(12) + U(44) + U(20);
        return new Rect((Screen.width - w) / 2f, Mathf.Max(U(8), (Screen.height - h) / 2f), w, h);
    }

    float ControlsRowsTop() { return U(18) + U(40) + U(28) + U(12); }

    Rect ControlsRow(Rect card, float colW, int i)
    {
        int c = i / ControlsPerCol, r = i % ControlsPerCol;
        return new Rect(card.x + U(24) + c * (colW + U(14)), card.y + ControlsRowsTop() + r * U(48), colW, U(42));
    }

    Rect ControlsMessage(Rect card)
    {
        return new Rect(card.x + U(24), card.y + ControlsRowsTop() + ControlsPerCol * U(48) + U(6), card.width - U(48), U(40));
    }

    Rect ControlsButton(Rect card, bool back)
    {
        float y = ControlsMessage(card).yMax + U(12);
        float bw = Measure("Back", 17) + U(56), rw = Measure("Reset to defaults", 17) + U(40);
        return back ? new Rect(card.xMax - U(24) - bw, y, bw, U(44))
            : new Rect(card.xMax - U(24) - bw - U(12) - rw, y, rw, U(44));
    }

    void DrawControls(Frame f)
    {
        ControlsRebind c = f.Controls;
        if (Event.current.type == EventType.Repaint)
            GUI.DrawTexture(new Rect(0, 0, Screen.width, Screen.height), Texture2D.whiteTexture, ScaleMode.StretchToFill, true, 0, A(Ink, 0.5f), 0, 0);
        Block(new Rect(0, 0, Screen.width, Screen.height));
        Rect card = ControlsCard(out float colW);
        LogControlsLayout(card, colW);
        Panel("panel", card);
        DrawIcon(new Rect(card.x + U(22), card.y + U(22), U(28), U(28)), Icon.Gear, Teal);
        Text(new Rect(card.x + U(58), card.y + U(16), card.width - U(120), U(40)), "Controls", 22, Ink);
        Rect close = new Rect(card.xMax - U(50), card.y + U(20), U(30), U(30));
        Panel(Hover(close) ? "optHover" : "opt", close, false);
        DrawIcon(new Rect(close.x + U(9), close.y + U(9), U(12), U(12)), Icon.Close, Denim);
        if (Hit(close, "Back to Settings (Esc)")) c.Hide();
        string hint = "Click an action, then press its new key  ·  " + Key(f, "SelectNext") + "/" + Key(f, "SelectPrevious")
            + " move  ·  " + Key(f, "Confirm") + " change  ·  Esc back";
        FitText(new Rect(card.x + U(24), card.y + U(58), card.width - U(48), U(28)), hint, 14, Denim, false, TextAnchor.MiddleLeft);

        float chipW = ControlsChipW();
        for (int i = 0; i < ControlsRebind.ActionCount; i++)
        {
            string action = InputActions.Names[i];
            Rect row = ControlsRow(card, colW, i);
            bool capturing = c.Capturing == action;
            bool changed = f.Access.BindingFor(action) != InputActions.DefaultBinding(action);
            Panel(capturing ? "tileOn" : c.Focus == i ? "optHi" : Hover(row) ? "optHover" : "opt", row, false);
            float cw = Mathf.Min(chipW, row.width * 0.5f);
            Rect chip = new Rect(row.xMax - cw - U(7), row.y + U(7), cw, row.height - U(14));
            FitText(new Rect(row.x + U(14), row.y, chip.x - row.x - U(20), row.height), ControlsRebind.Label(action), 15,
                capturing ? White : Ink, true, TextAnchor.MiddleLeft);
            string key = capturing ? "Press a key" : c.Binding(action);
            Panel(capturing ? "optHi" : changed ? "spdOn" : "spd", chip, false);
            FitText(new Rect(chip.x + U(4), chip.y, chip.width - U(8), chip.height), key, 14,
                capturing ? Ink : changed ? White : Denim, true, TextAnchor.MiddleCenter);
            if (Hit(row, ControlsRebind.Label(action) + ": " + key + " (click, then press a key)")) { StopTalkCapture(f); c.Activate(i); }
        }
        if (f.Voice != null) DrawTalkRow(f, ControlsRow(card, colW, ControlsRebind.TalkRowIndex), chipW);

        Rect msg = ControlsMessage(card);
        bool talking = f.Voice != null && f.Voice.Capturing;
        string text = talking ? f.Voice.PageMessage : c.Message.Length > 0 ? c.Message : "Changes apply at once and are saved with your settings.";
        if (c.MessageIsError && !talking)
        {
            Panel("error", msg, false);
            Rect mark = new Rect(msg.x + U(12), msg.center.y - U(9), U(18), U(18));
            DrawIcon(mark, Icon.Disc, Rust);
            Text(mark, "!", 12, White, true, TextAnchor.MiddleCenter);
            FitText(new Rect(msg.x + U(40), msg.y, msg.width - U(52), msg.height), text, 15, RustDark, true, TextAnchor.MiddleLeft);
        }
        else
        {
            bool done = c.Message.Length > 0 && c.Capturing == null && !talking;
            if (done) DrawIcon(new Rect(msg.x + U(12), msg.center.y - U(9), U(18), U(18)), Icon.Check, Teal);
            FitText(new Rect(msg.x + (done ? U(40) : U(4)), msg.y, msg.width - U(52), msg.height), text, 15,
                done ? TealDark : OliveDark, done, TextAnchor.MiddleLeft);
        }

        for (int b = 0; b < 2; b++)
        {
            bool back = b == 1;
            int index = back ? ControlsRebind.BackRow : ControlsRebind.ResetRow;
            Rect r = ControlsButton(card, back);
            Panel(c.Focus == index ? "optHi" : Hover(r) ? "optHover" : "opt", r, false);
            if (back) DrawIcon(new Rect(r.x + U(16), r.center.y - U(7), U(14), U(14)), Icon.Left, Denim);
            else DrawIcon(new Rect(r.x + U(14), r.center.y - U(8), U(16), U(16)), Icon.Reload, Rust);
            FitText(new Rect(r.x + U(36), r.y, r.width - U(44), r.height), back ? "Back" : "Reset to defaults", 17,
                back ? Ink : RustDark, true, TextAnchor.MiddleLeft);
            if (Hit(r, back ? "Back to Settings (Esc)" : "Put every key back to its default")) { StopTalkCapture(f); c.Activate(index); }
        }
    }

    // The talk key row: the same capture and refusal rules as Settings > Voice.
    void DrawTalkRow(Frame f, Rect row, float chipW)
    {
        AlphaVoice v = f.Voice;
        ControlsRebind c = f.Controls;
        bool capturing = v.Capturing;
        bool changed = v.Settings.TalkKey != VoiceSettings.DefaultTalkKey;
        Panel(capturing ? "tileOn" : c.Focus == ControlsRebind.TalkRowIndex ? "optHi" : Hover(row) ? "optHover" : "opt", row, false);
        float cw = Mathf.Min(chipW, row.width * 0.5f);
        Rect chip = new Rect(row.xMax - cw - U(7), row.y + U(7), cw, row.height - U(14));
        FitText(new Rect(row.x + U(14), row.y, chip.x - row.x - U(20), row.height), TalkLabel, 15, capturing ? White : Ink, true, TextAnchor.MiddleLeft);
        string key = capturing ? "Press a key" : ControlsRebind.Display(v.Settings.TalkKey);
        Panel(capturing ? "optHi" : changed ? "spdOn" : "spd", chip, false);
        FitText(new Rect(chip.x + U(4), chip.y, chip.width - U(8), chip.height), key, 14,
            capturing ? Ink : changed ? White : Denim, true, TextAnchor.MiddleCenter);
        if (Hit(row, TalkLabel + ": " + key + " (click, then press a key)")) c.Activate(ControlsRebind.TalkRowIndex);
    }

    static void StopTalkCapture(Frame f) { if (f.Voice != null) f.Voice.CancelCapture(); }

    static string Key(Frame f, string action) { return ControlsRebind.Display(f.Access.BindingFor(action)); }

    // The CONTROLS-LOGO session driver reads these row centres (logged when the layout changes); no other consumer.
    void LogControlsLayout(Rect card, float colW)
    {
        string key = Screen.width + "x" + Screen.height + ":" + Mathf.RoundToInt(k * 1000f) + ":" + Mathf.RoundToInt(kf * 1000f);
        if (key == controlsLayoutKey) return;
        controlsLayoutKey = key;
        StringBuilder line = new StringBuilder("ALPHA controls layout w=" + Screen.width + " h=" + Screen.height);
        for (int i = 0; i < ControlsRebind.ActionCount; i++) line.Append(" row" + i + "=" + Centre(ControlsRow(card, colW, i)));
        line.Append(" talk=" + Centre(ControlsRow(card, colW, ControlsRebind.TalkRowIndex)));
        line.Append(" reset=" + Centre(ControlsButton(card, false)) + " back=" + Centre(ControlsButton(card, true)));
        line.Append(" card=" + Mathf.RoundToInt(card.width).ToString(CultureInfo.InvariantCulture) + "x"
            + Mathf.RoundToInt(card.height).ToString(CultureInfo.InvariantCulture));
        Debug.Log(line.ToString());
    }
}

// Keys for the open Controls page, read in AlphaDirector.Update instead of the game's own input.
public static class AlphaControlsInput
{
    static readonly KeyCode[] Keyboard = KeyboardKeys();

    public static void Handle(ControlsRebind c, Accessibility access)
    {
        if (c.Capturing != null)
        {
            if (!Input.anyKeyDown) return;
            foreach (KeyCode k in Keyboard)
                if (Input.GetKeyDown(k)) { c.Press(k.ToString()); return; }
            return;
        }
        if (Down(access, "SelectNext")) c.Move(1);
        else if (Down(access, "SelectPrevious")) c.Move(-1);
        else if (Down(access, "Confirm")) c.Activate(c.Focus);
        else if (Input.GetKeyDown(KeyCode.Escape) || Down(access, "OpenSettings")) c.Hide();
    }

    static bool Down(Accessibility access, string action)
    {
        KeyCode k;
        return Enum.TryParse(access.BindingFor(action), out k) && Input.GetKeyDown(k);
    }

    // Keyboard keys only: mouse buttons stay free to click the page.
    static KeyCode[] KeyboardKeys()
    {
        List<KeyCode> keys = new List<KeyCode>();
        foreach (KeyCode k in Enum.GetValues(typeof(KeyCode)))
            if (k > KeyCode.None && k < KeyCode.Mouse0 && !keys.Contains(k)) keys.Add(k);
        return keys.ToArray();
    }
}
